import java.util.*;public class ChatFilter{public static void main(String[]x){String[] logs={"10:05 alice Hello there","bad line","10:07 bob Meeting at noon"};Scanner s=new Scanner(System.in);System.out.print("Keyword: ");String k=s.nextLine().toLowerCase();StringBuilder out=new StringBuilder();int count=0;for(String line:logs){String[] p=line.split(" ",3);if(p.length<3)continue;if(p[2].toLowerCase().contains(k)){count++;out.append(p[0]).append(" ").append(p[1]).append(": ").append(p[2]).append('\n');}}System.out.println("Matches: "+count);System.out.print(out);}}
